    # remaining two phases.
    residues = {v: {(c-r) % 3 for r,row in enumerate(grid) for c,x in enumerate(row) if x == v} for v in colors}
    a = next(v for v in colors if len(residues[v]) == 1)
    phase = next(iter(residues[a]))
    b = next(v for v in colors if v != a)
    return [[a if (c-r) % 3 == phase else b for c in range(w)] for r in range(h)]

